/**
 * Walrus Names Gateway — Cloudflare Worker
 *
 * Serves `.epoch` sites via subdomains:
 *   esempio.epochsui.com → resolves "esempio" on-chain → fetches blob from Walrus → serves HTML
 *
 * Flow:
 *   1. Extract subdomain from request hostname (e.g. "esempio" from "esempio.epochsui.com")
 *   2. Call Sui RPC to read blob_id from the Registry shared object
 *   3. Fetch blob content from Walrus aggregator
 *   4. Return response with correct Content-Type
 *
 * DNS setup (Cloudflare dashboard):
 *   CNAME  *  →  walrus-names-gateway.<account>.workers.dev  (proxied)
 *   Then add Custom Domain *.epochsui.com in Worker settings
 */

export interface Env {
  NETWORK: string  // "testnet" | "mainnet"
}

/* ── On-chain constants ──────────────────────────────────────── */

const CONTRACTS = {
  testnet: {
    rpc:        'https://fullnode.testnet.sui.io:443',
    packageId:  '0x159ced95ba4b73994f6c70c7bfe4cc9aee62abcf35a358185364e3af9bc231e3',
    registryId: '0xce19bb7e07bca68a5074534e0878580365b45ec9f11a0231dddfc25106fd216b',
    walrusAggregator: 'https://aggregator.walrus-testnet.walrus.space',
  },
  mainnet: {
    rpc:        'https://fullnode.mainnet.sui.io:443',
    packageId:  '0x5dd1fb9f784129f0815c8e54ed917ad698401c0900ebeb1525f37fac98a94dda',
    registryId: '0xa6d9e91daa40dbff259838c9f5bd6448d8f08e9b2a3da02c5d4d3c88ce5666d1',
    walrusAggregator: 'https://aggregator.walrus-mainnet.walrus.space',
  },
}

/* ── OG Image generator ──────────────────────────────────────── */

function generateOgImage(name: string): Response {
  const LOGO_B64 = "data:image/png;base64,"
  const svg = `<svg width="1200" height="630" viewBox="0 0 1200 630" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <radialGradient id="bg" cx="50%" cy="40%" r="60%">
      <stop offset="0%" stop-color="#0a1628"/>
      <stop offset="100%" stop-color="#040d1a"/>
    </radialGradient>
    <linearGradient id="fade" x1="0" y1="0" x2="0" y2="1">
      <stop offset="40%" stop-color="rgba(4,13,26,0)"/>
      <stop offset="100%" stop-color="rgba(4,13,26,1)"/>
    </linearGradient>
  </defs>

  <!-- Background -->
  <rect width="1200" height="630" fill="url(#bg)"/>

  <!-- Logo (transparent PNG, centered) -->
  <image href="${LOGO_B64}" x="400" y="20" width="400" height="400" preserveAspectRatio="xMidYMid meet"/>

  <!-- Fade overlay for text area -->
  <rect width="1200" height="630" fill="url(#fade)"/>

  <!-- Site name -->
  <text x="600" y="530" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
        font-size="80" font-weight="700" fill="white" text-anchor="middle"
        letter-spacing="-2">${name}.epoch</text>

  <!-- Subtitle -->
  <text x="600" y="590" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
        font-size="22" fill="rgba(111,188,240,0.85)" text-anchor="middle"
        letter-spacing="4">EPOCH SITES</text>

  <!-- Bottom accent -->
  <rect x="0" y="624" width="1200" height="6" fill="rgba(111,188,240,0.5)" rx="3"/>
</svg>`

  return new Response(svg, {
    headers: {
      'Content-Type': 'image/svg+xml',
      'Cache-Control': 'public, max-age=86400',
      'Access-Control-Allow-Origin': '*',
    },
  })
}

/* ── Main handler ────────────────────────────────────────────── */

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url      = new URL(request.url)
    const hostname = url.hostname  // e.g. "esempio.epochsui.com"

    // OG image route: og.epochsui.com/:name or /og/:name
    if (hostname.startsWith('og.') || url.pathname.startsWith('/og/')) {
      const name = hostname.startsWith('og.')
        ? url.pathname.replace(/^\//, '').split('/')[0] || 'epoch'
        : url.pathname.replace('/og/', '').split('/')[0] || 'epoch'
      return generateOgImage(name.toLowerCase().replace(/[^a-z0-9-]/g, ''))
    }

    // Extract the subdomain (everything before the first dot)
    const parts = hostname.split('.')
    if (parts.length < 3) {
      return notFound('Not a valid .epoch site URL.')
    }

    const name    = parts[0].toLowerCase()

    // Reserved infrastructure subdomains: NON vanno risolti come nomi .epoch.
    // Sono proxati attraverso questo Worker (wildcard *.epochsui.com), quindi
    // senza questo check mostrerebbero "Site Not Found". Li reindirizziamo al sito.
    const RESERVED = new Set([
      'www', 'mail', 'webmail', 'autoconfig', 'autodiscover',
      'smtp', 'imap', 'pop', 'pop3', 'mx', 'ftp', 'ns1', 'ns2',
      'api', 'cpanel', 'og', 'indexer',
    ])
    if (RESERVED.has(name)) {
      return Response.redirect('https://epochsui.com', 301)
    }

    // MCP server: proxy trasparente verso il Worker epoch-mcp.
    // Così l'endpoint pubblico è SOLO epoch-mcp.epochsui.com (nessun workers.dev visibile)
    // e non dipendiamo dalla precedenza custom-domain vs wildcard.
    if (name === 'mcp' || name === 'epoch-mcp') {
      const target = new URL(request.url)
      target.hostname = 'epoch-mcp.pupazzipunkapi.workers.dev'
      return fetch(new Request(target.toString(), request))
    }

    // Verified Vault badge: proxy trasparente verso il Worker epoch-badge.
    // Endpoint pubblico: epoch-badge.epochsui.com/badge/<id>.svg e /embed/<id>.
    if (name === 'epoch-badge' || name === 'badge') {
      const target = new URL(request.url)
      target.hostname = 'epoch-badge.pupazzipunkapi.workers.dev'
      return fetch(new Request(target.toString(), request))
    }

    // Ecosystem brain: proxy trasparente verso il Worker epoch-ecosystem.
    // Endpoint pubblico: ecosystem.epochsui.com
    if (name === 'ecosystem' || name === 'epoch-ecosystem') {
      const target = new URL(request.url)
      target.hostname = 'epoch-ecosystem.pupazzipunkapi.workers.dev'
      return fetch(new Request(target.toString(), request))
    }

    const network = (env.NETWORK === 'mainnet' ? 'mainnet' : 'testnet') as 'mainnet' | 'testnet'
    const cfg     = CONTRACTS[network]

    if (!cfg.packageId || !cfg.registryId) {
      return errorResponse('Mainnet not yet deployed.')
    }

    // Validate name format (same rules as the contract)
    if (!isValidName(name)) {
      return notFound(`"${name}" is not a valid .epoch name.`)
    }

    // 1. Resolve name → blob_id on-chain.
    //    Fallback: il sottodominio può essere un object ID in Base36
    //    (<objectid-base36>.epochsui.com, come i portal Walrus Sites) →
    //    il sito è raggiungibile anche senza passare dal lookup del nome.
    let blobId = ''
    try {
      blobId = await resolveName(cfg.rpc, cfg.packageId, cfg.registryId, name)
    } catch (e) {
      return errorResponse(`Failed to query on-chain registry: ${(e as Error).message}`)
    }

    if (!blobId) {
      const objectId = base36ToObjectId(name)
      if (objectId) {
        try { blobId = await resolveObjectId(cfg.rpc, cfg.packageId, cfg.registryId, objectId) } catch { /* fallthrough */ }
      }
    }

    if (!blobId) {
      return notFound(`"${name}.epoch" is not registered.`)
    }

    // 2. Fetch blob from Walrus
    const blob = await fetchBlob(cfg.walrusAggregator, blobId)
    if (!blob) {
      return notFound('Blob not found on Walrus.')
    }

    // 3. Manifest? → sito multi-pagina: risolvi il pathname richiesto e servi
    //    il blob corrispondente. I blob non-manifest restano single-page (legacy).
    const manifest = parseManifest(blob.content)
    if (manifest) {
      return serveFromManifest(manifest, url.pathname, cfg.walrusAggregator, name, blobId)
    }

    // 4. Single-blob site (legacy)
    return new Response(blob.content, {
      status:  200,
      headers: {
        'Content-Type':              blob.contentType ?? guessContentType(blobId),
        'X-Epoch-Name':              `${name}.epoch`,
        'X-Walrus-Blob-Id':          blobId,
        'Cache-Control':             'public, max-age=300',  // 5 min cache
        'Access-Control-Allow-Origin': '*',
      },
    })
  },
}

/* ── Walrus fetch ────────────────────────────────────────────── */

async function fetchBlob(
  aggregator: string,
  blobId:     string,
): Promise<{ content: ArrayBuffer; contentType: string | null } | null> {
  try {
    const res = await fetch(`${aggregator}/v1/blobs/${blobId}`, {
      headers: { 'User-Agent': 'walrus-names-gateway/1.0' },
    })
    if (!res.ok) return null
    return { content: await res.arrayBuffer(), contentType: res.headers.get('content-type') }
  } catch {
    return null
  }
}

/* ── Multi-page manifest ─────────────────────────────────────────
 * Un sito multi-pagina è un blob JSON con questa shape:
 *   {
 *     "epoch-manifest": 1,
 *     "routes": { "/": "<blobId>", "/about": "<blobId>", "/style.css": "<blobId>" },
 *     "404": "<blobId>"            // opzionale, pagina not-found custom
 *   }
 * Il Content-Type è dedotto dall'estensione del path ("/about" → html).
 * Retrocompatibile: blob non-JSON (o JSON senza "epoch-manifest") = sito
 * single-page servito così com'è. */

interface SiteManifest {
  routes:   Record<string, string>
  notFound?: string
}

const MANIFEST_MAX_BYTES = 256 * 1024 // un manifest più grande di così non è un manifest

function parseManifest(content: ArrayBuffer): SiteManifest | null {
  if (content.byteLength > MANIFEST_MAX_BYTES) return null
  try {
    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: false }).decode(content)
    const j    = JSON.parse(text)
    if (!j || typeof j !== 'object' || !j['epoch-manifest']) return null
    if (!j.routes || typeof j.routes !== 'object') return null
    return { routes: j.routes as Record<string, string>, notFound: typeof j['404'] === 'string' ? j['404'] : undefined }
  } catch {
    return null
  }
}

const MIME_BY_EXT: Record<string, string> = {
  html: 'text/html; charset=utf-8', htm: 'text/html; charset=utf-8',
  css:  'text/css; charset=utf-8',  js:  'application/javascript; charset=utf-8',
  json: 'application/json',         xml: 'application/xml',  txt: 'text/plain; charset=utf-8',
  svg:  'image/svg+xml', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg',
  gif:  'image/gif', webp: 'image/webp', ico: 'image/x-icon', avif: 'image/avif',
  woff: 'font/woff', woff2: 'font/woff2', ttf: 'font/ttf', otf: 'font/otf',
  mp3:  'audio/mpeg', mp4: 'video/mp4', webm: 'video/webm', pdf: 'application/pdf',
  wasm: 'application/wasm',
}

function mimeFromPath(path: string): string {
  const ext = path.includes('.') ? path.split('.').pop()!.toLowerCase() : ''
  return MIME_BY_EXT[ext] ?? 'text/html; charset=utf-8' // path senza estensione = pagina html
}

async function serveFromManifest(
  manifest:   SiteManifest,
  rawPath:    string,
  aggregator: string,
  name:       string,
  rootBlobId: string,
): Promise<Response> {
  // Normalizza: senza trailing slash (tranne root), decodifica %xx
  let path = decodeURIComponent(rawPath)
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1)
  if (!path.startsWith('/')) path = '/' + path

  // Lookup: esatto → variante .html → index annidato
  const target =
    manifest.routes[path] ??
    manifest.routes[`${path}.html`] ??
    manifest.routes[`${path}/index.html`] ??
    // link scritti con .html ma route registrata senza estensione (es. /portfolio.html → /portfolio)
    (path.endsWith('.html') ? manifest.routes[path.replace(/\.html$/, '')] ?? (path === '/index.html' ? manifest.routes['/'] : undefined) : undefined) ??
    (path === '/' ? manifest.routes['/index.html'] : undefined)

  if (!target) {
    // 404 custom del sito, se presente
    if (manifest.notFound) {
      const nf = await fetchBlob(aggregator, manifest.notFound)
      if (nf) return new Response(nf.content, {
        status: 404,
        headers: { 'Content-Type': 'text/html; charset=utf-8', 'X-Epoch-Name': `${name}.epoch` },
      })
    }
    return notFound(`No page at "${path}" on ${name}.epoch.`)
  }

  const blob = await fetchBlob(aggregator, target)
  if (!blob) return notFound(`Blob for "${path}" not found on Walrus.`)

  return new Response(blob.content, {
    status:  200,
    headers: {
      'Content-Type':              mimeFromPath(path),
      'X-Epoch-Name':              `${name}.epoch`,
      'X-Walrus-Blob-Id':          target,
      'X-Epoch-Manifest':          rootBlobId,
      'Cache-Control':             'public, max-age=300',
      'Access-Control-Allow-Origin': '*',
    },
  })
}

/* ── Base36 objectID resolution ──────────────────────────────────
 * I sottodomini DNS non ammettono "0x" né maiuscole, quindi (come i portal
 * Walrus Sites) un object ID può essere codificato in Base36:
 *   <objectid-base36>.epochsui.com
 * Supportiamo sia l'oggetto NameCap (ha il campo `name` → lookup nel registry)
 * sia oggetti che espongono direttamente `blob_id`. */

function base36ToObjectId(s: string): string {
  // Un object ID di 32 byte in Base36 è ~45-50 caratteri, solo [0-9a-z].
  // I nomi .epoch normali sono molto più corti → niente ambiguità in pratica.
  if (s.length < 40 || s.length > 52 || !/^[0-9a-z]+$/.test(s)) return ''
  let n = 0n
  for (const c of s) n = n * 36n + BigInt(parseInt(c, 36))
  const hex = n.toString(16)
  if (hex.length > 64) return ''
  return '0x' + hex.padStart(64, '0')
}

async function resolveObjectId(
  rpc:        string,
  packageId:  string,
  registryId: string,
  objectId:   string,
): Promise<string> {
  const res = await fetch(rpc, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({
      jsonrpc: '2.0', id: 1,
      method:  'sui_getObject',
      params:  [objectId, { showContent: true }],
    }),
  })
  const json   = await res.json() as any
  const fields = json.result?.data?.content?.fields
  if (!fields) return ''

  // Oggetto col blob_id diretto (es. NameRecord wrappato in dynamic field)
  if (typeof fields.blob_id === 'string' && fields.blob_id) return fields.blob_id
  const nested = fields.value?.fields
  if (nested && typeof nested.blob_id === 'string' && nested.blob_id) return nested.blob_id

  // NameCap: ha il campo `name` → risolvi via registry
  const nm = typeof fields.name === 'string' ? fields.name : (typeof nested?.name === 'string' ? nested.name : '')
  if (nm && isValidName(nm)) return resolveName(rpc, packageId, registryId, nm)

  return ''
}

/* ── On-chain resolver ───────────────────────────────────────── */

/**
 * Reads the NameRecord from the Registry Table.
 * In Sui Move, Table<K,V> stores entries as dynamic fields on the TABLE's own
 * internal object ID — NOT on the parent Registry object.
 * We must first fetch the Registry to get the Table's internal ID, then
 * query the dynamic field on that ID.
 */
async function resolveName(
  rpc:        string,
  packageId:  string,
  registryId: string,
  name:       string,
): Promise<string> {
  // Step 1: fetch Registry to get the Table's internal object ID
  const regRes  = await fetch(rpc, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({
      jsonrpc: '2.0', id: 1,
      method:  'sui_getObject',
      params:  [registryId, { showContent: true }],
    }),
  })
  const regJson = await regRes.json() as any
  const tableId = regJson.result?.data?.content?.fields?.records?.fields?.id?.id
  if (!tableId) return ''

  // Step 2: query the dynamic field on the Table's internal ID
  const body = {
    jsonrpc: '2.0',
    id:      2,
    method:  'suix_getDynamicFieldObject',
    params:  [
      tableId,
      {
        type:  '0x1::string::String',
        value: name,
      },
    ],
  }

  const res  = await fetch(rpc, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify(body),
  })
  const json = await res.json() as any

  if (json.error || !json.result?.data) return ''

  // The NameRecord fields are nested inside the dynamic field's content
  const fields = json.result.data?.content?.fields?.value?.fields
  if (!fields) return ''

  return fields.blob_id ?? ''
}

/* ── Helpers ─────────────────────────────────────────────────── */

function isValidName(name: string): boolean {
  if (name.length < 3 || name.length > 63) return false
  if (name.startsWith('-') || name.endsWith('-')) return false
  return /^[a-z0-9-]+$/.test(name)
}

function guessContentType(blobId: string): string {
  // Most sites will be HTML; SVG/JSON are also common
  if (blobId.endsWith('.svg')) return 'image/svg+xml'
  if (blobId.endsWith('.json')) return 'application/json'
  return 'text/html; charset=utf-8'
}

/** Escape HTML — error/404 messages can echo request-controlled strings (e.g. the
 *  requested path), so they MUST be escaped before interpolation into the page. */
function escHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

function notFound(msg: string): Response {
  return new Response(notFoundPage(escHtml(msg)), {
    status:  404,
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  })
}

function errorResponse(msg: string): Response {
  return new Response(errorPage(escHtml(msg)), {
    status:  500,
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  })
}

